public class InnerApplicationVersionImageConfigurationFactory(Action<Humidifier.ElasticBeanstalk.ApplicationVersionTypes.ImageConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.ElasticBeanstalk.ApplicationVersionTypes.ImageConfiguration>
{

    internal InnerApplicationVersionImageBuildConfigurationFactory BuildFactory { get; set; }

    internal InnerApplicationVersionImageSourceFactory SourceFactory { get; set; }

    protected override Humidifier.ElasticBeanstalk.ApplicationVersionTypes.ImageConfiguration Create()
    {
        var imageConfigurationResult = CreateImageConfiguration();
        factoryAction?.Invoke(imageConfigurationResult);

        return imageConfigurationResult;
    }

    private Humidifier.ElasticBeanstalk.ApplicationVersionTypes.ImageConfiguration CreateImageConfiguration()
    {
        var imageConfigurationResult = new Humidifier.ElasticBeanstalk.ApplicationVersionTypes.ImageConfiguration();

        return imageConfigurationResult;
    }
    public override void CreateChildren(Humidifier.ElasticBeanstalk.ApplicationVersionTypes.ImageConfiguration result)
    {
        base.CreateChildren(result);

        result.Build ??= BuildFactory?.Build();
        result.Source ??= SourceFactory?.Build();
    }

} // End Of Class

